     "disc": "No es provisional ni improvisado: es <b>permanente y subordinado</b>. Existe una cosa principal y esta vive a su lado, revisada y lista, para el día en que la principal falle. De ahí <i>___ verb</i>, <i>___ power</i>, <i>___ troops</i>.",
     "tone": "neu",
     "axisPos": 45,
     "ej": "The main pump has never once failed, and the ___ one has been serviced every spring for twenty years in case it does.",
     "twin": "makeshift",
     "whyNotTwin": "auxiliary es <b>equipo propio, previsto y mantenido</b>, que espera su turno; makeshift es <b>lo que se improvisó</b> porque el equipo propio no estaba. Una bomba de reserva no es un apaño.",
