     "w": "fledgling",
     "pos": "adj",
     "def": "newly formed and not yet established",
     "disc": "Del <b>pollo que aún no vuela</b>. Lo que afirma es <b>la edad</b>, no la calidad de los medios: la institución está bien constituida — tiene estatuto, personal y sello — y lo único que le falta es <b>tiempo detrás</b>.",
     "tone": "neu",
     "axisPos": 65,
     "ej": "Four months after the founding, the ___ treasury had its charter, its staff sworn in and a stamp of its own — and not one year of accounts behind it.",
     "twin": "makeshift",
     "whyNotTwin": "fledgling dice que <b>acaba de nacer</b> y que va a durar; makeshift dice que <b>se armó con lo que había</b> y que se desmontará cuando llegue lo bueno. Lo nuevo puede estar impecablemente hecho.",
