     "pos": "adj",
     "def": "with no end date and no limit set to it",
     "disc": "Lo que le falta no es solidez sino <b>plazo</b>: nadie ha fijado cuándo termina ni qué haría que terminase. Por eso su terreno propio son las <b>suspensiones, detenciones y aplazamientos</b>, donde lo grave es justamente que no haya fecha.",
     "tone": "neu",
     "axisPos": 90,
     "ej": "The suspension was ___: no review date, no end date, and nobody at the ministry would say what would have to happen for it to be lifted.",
     "twin": "makeshift",
     "whyNotTwin": "indefinite mide <b>el plazo</b> — no lo hay —; makeshift mide <b>el material</b> — es prestado. Una suspensión sin fecha puede estar perfectamente reglamentada, y un apaño de dos mesas puede tener fecha de retirada.",
