     "pos": "v",
     "def": "copy the observable features of something, often to mock it",
     "disc": "Reproduce <b>lo que se ve y se oye</b>: la tos, el andar, la pausa antes del apellido. No hay admiración ni ambición de igualar un mérito — por eso sirve para la burla y para el material que imita la veta del roble.",
     "tone": "neu",
     "axisPos": 8,
     "ej": "He could ___ the headmaster's cough, his walk and the pause before he said anyone's surname; the staff room laughed and the boy was expelled anyway.",
     "twin": "emulate",
     "whyNotTwin": "mimic copia <b>rasgos observables</b> y no supone respeto ninguno; emulate persigue <b>el logro</b> de un modelo admirado. Nadie emula una tos: no es un mérito que igualar.",
