     "pos": "v",
     "def": "strive to match the achievement of a model one admires",
     "disc": "Lo que se persigue es <b>el resultado</b>, no la forma: se puede emular un sistema sin copiar ni una de sus piezas. Trae dentro <b>admiración y esfuerzo</b>, y el listón está en llegar a la misma altura, no en superarla.",
     "tone": "pos",
