     "pos": "v",
     "def": "go beyond the limits of the category one belongs to",
     "disc": "Lo que se rebasa es <b>una categoría, no un rival</b>: el género, la etiqueta, la condición. Por eso su objeto típico es un marco — <i>___ the genre</i>, <i>___ politics</i> — y no una persona ni una obra concreta a la que ganarle.",
     "tone": "pos",
