     "pos": "v",
     "def": "outshine someone so completely that they are forgotten",
     "disc": "Exige <b>dos partes y una sola luz</b>: lo que crece deja a oscuras a lo que había. Su prueba está siempre en lo que le pasa al otro — pasa a ser nota a pie de página, se deja de tocar, se cataloga bajo el nombre del que vino después.",
     "tone": "neu",
