   "note": "Se parecen en la página y en nada más. <b>abate</b> es una tormenta que cede; <b>abet</b> es complicidad — casi siempre en la fórmula fija \"aid and abet\".",
   "aEj": "They waited under the awning until the downpour ___d.",
