   "note": "<b>censure</b> castiga a una persona con una condena pública; <b>censor</b> corta un texto o una imagen. El objeto delata cuál es: se censura a un senador, se censura una película.",
   "aEj": "The committee voted to ___ the senator for accepting the gifts.",
