   "b": "turgid",
   "bothInList": true,
   "aDef": "cloudy, muddied by suspended particles",
   "bDef": "swollen; or pompous and overblown",
   "note": "<b>turbid</b> es agua sucia — falta de claridad por suspensión. <b>turgid</b> es hinchazón: un tejido inflamado, o una prosa inflada de solemnidad. Los dos se aplican a la prosa, pero turbid la vuelve confusa y turgid la vuelve pomposa.",
   "aEj": "The river ran ___ for a week after the landslide.",
   "bEj": "His ___ acceptance speech piled abstraction on abstraction for forty minutes."
