   "ghost": "proscribe",
   "aDef": "to order or lay down authoritatively",
   "bDef": "to forbid outright",
   "note": "Son <b>opuestos</b> y difieren en dos letras. <b>prescribe</b> manda hacer; <b>proscribe</b> manda no hacer. Solo prescribe está en tu lista, pero proscribe aparece como distractor en el examen precisamente por esto.",
