   "aDef": "corrupt, open to bribery",
   "bDef": "minor and forgivable",
   "note": "Una sola letra separa una acusación grave de una excusa. <b>venal</b> es un juez que se vende; <b>venial</b> es un pecado menor. Solo venal está en tu lista.",
   "aEj": "A ___ inspector signed off on the building without ever entering it.",
