   "aDef": "to openly defy a rule",
   "bDef": "to display something ostentatiously",
   "note": "<b>flout</b> tiene por objeto una <i>norma</i>: se desacata una ley, una convención. <b>flaunt</b> tiene por objeto una <i>posesión o cualidad</i>: se ostenta la riqueza. Regla: si el objeto es una regla, es flout.",
