   "aDef": "prudent, able to keep a confidence",
   "bDef": "separate, individually distinct",
   "note": "Mismas letras, distinto orden al final. <b>discreet</b> describe conducta; <b>discrete</b> describe estructura — unidades separadas. El sustantivo de discrete es <i>discreteness</i>; el de discreet es <i>discretion</i>.",
