   "ghost": "credulous",
   "aDef": "believable, worthy of trust",
   "bDef": "too ready to believe anything",
   "note": "<b>credible</b> califica al <i>mensaje</i>; <b>credulous</b> califica al <i>que escucha</i>. Un testigo credible dice cosas creíbles; un jurado credulous se las cree todas. Añade <i>creditable</i> (meritorio) y son tres.",
